with kept_keys as (select customer_id, id from subscriptions except all select customer_id, id from subscriptions where customer_id in (1, 8, 25, 26)), reconciled as (select s.* from subscriptions s inner join kept_keys k on s.customer_id = k.customer_id and s.id = k.id) select case when monthly_fee >= 233 then 'LARGE' else 'SMALL' end as monthly_fee_tier, round(avg(monthly_fee), 2) as avg_monthly_fee, size(collect_set(plan)) as num_plans, count(*) filter (where status = 'PAUSED') as paused_rows, round(sum(monthly_fee) / nullif(count(case when status = 'PAUSED' then 1 end), 0), 2) as monthly_fee_per_paused, count(case when plan = 'premium' then 1 end) as premium_count, sum(case when status = 'PAUSED' then monthly_fee else 0 end) as paused_monthly_fee from reconciled group by case when monthly_fee >= 233 then 'LARGE' else 'SMALL' end order by avg_monthly_fee;
